import{advance,choose,random}from './engine.js';import{automaticAction,decisionUid}from './decisions.js';import{importantEvent,readingMs}from './time-config.js';
export const STORY_CONFIG={maxDaysPerSlice:60,storyWaitMin:1600,storyWaitMax:9000,observeWaitMin:800,observeWaitMax:4500};
export function simulationMode(s){const c=s.chronicle;c.preferences.progressMode??='story';return c.preferences.progressMode;}
export function nextStoryBeat(s,{maxDays=STORY_CONFIG.maxDaysPerSlice,observe=simulationMode(s)==='observe'}={}){const from=s.log.length,start=s.day;let days=0;while(s.alive&&days<maxDays){if(s.pending){if(s.mode!=='observe')break;choose(s,automaticAction(s,random),decisionUid(s));s.presentation=null;if(s.log.length>from)break;}const n=s.log.length;advance(s,1);days++;if(s.pending||!s.alive)break;const added=s.log.slice(n);if(added.some(e=>importantEvent(e)||e.id==='decision-outcome'||!['smell','sleep','world','play','family','street','shelter','companion-routine'].includes(e.id)))break;if(!observe&&added.length)break;if(observe&&added.length&&days>=14)break;}
const events=s.log.slice(from);const important=events.some(importantEvent);const text=events.map(e=>e.text).join(' ');return {from,start,end:s.day,days,events,important,text,waitMs:Math.max(observe?800:1600,Math.min(observe?4500:9000,readingMs(text)*(observe?.55:.8)))};}
// Summaries are presentation only; every raw event and every internal day is retained.
export function timelineEntries(s,{observe=simulationMode(s)==='observe'}={}){const result=[],resolved=new Set(s.log.filter(e=>e.id==='decision-outcome').map(e=>e.decisionUid));let group=null;for(let i=0;i<s.log.length;i++){const e=s.log[i];if(e.id==='choice'||e.resolvedDecisionUid&&resolved.has(e.resolvedDecisionUid))continue;if(e.id==='decision'&&s.log.slice(i+1,i+8).some(r=>r.id==='decision-outcome'&&r.prompt===e.text))continue;const ordinary=['smell','sleep','world','play','family','street','shelter','companion-routine'].includes(e.id);if(observe&&ordinary){if(group&&e.day-group.start<=30){group.day=e.day;group.count++;group.text=`${group.start}일–${group.day}일 · ${group.count}개의 일상 기록. ${e.text}`;continue}group={...e,index:i,start:e.day,count:1,summary:true};result.push(group)}else{group=null;result.push({...e,index:i})}}return result;}

export function beatDelay(beat,speed=1){const scaled=Math.max(500,beat.waitMs/Math.max(1,Number(speed)||1));return beat.important||beat.text.length>120?Math.max(scaled,readingMs(beat.text)):scaled;}
